#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    long long total[101] = {0};
    long long received_at[101] = {0};
    int seen[101] = {0};
    int waiting[101] = {0};
    long long time = 0;
    long long gap = 1;

    for (int i = 0; i < n; i++) {
        char type;
        int x;
        scanf(" %c %d", &type, &x);

        if (type == 'T') {
            gap = x;
        } else {
            time += gap;
            gap = 1;
            seen[x] = 1;

            if (type == 'R') {
                received_at[x] = time;
                waiting[x] = 1;
            } else {
                total[x] += time - received_at[x];
                waiting[x] = 0;
            }
        }
    }

    for (int i = 1; i <= 100; i++) {
        if (seen[i]) {
            printf("%d %lld\n", i, waiting[i] ? -1LL : total[i]);
        }
    }

    return 0;
}
